SELECT *
FROM CMCDV
WHERE 1=1
    AND CMCDKY = #{CMCDKY}
    AND CDESC1 = #{CDESC1}

SELECT DISTINCT M12.MACH_CD AS VALUE_COL, M12.MACH_NM AS TEXT_COL FROM TB_MAS012 M12 left join TB_MAS013 M13 on M12.PROC_CD = M13.PROC_CD WHERE 1=1
AND M13.WERKS = #{WERKS}
AND M12.PROC_CD = #{PROC_CD}
AND TRIM(M12.MACH_CD) IS NOT NULL ORDER BY M12.MACH_CD

select NVL(MAX(PRC_SEQNO), 0) AS PRC_SEQNO
from TB_QLT020
where 1=1
    and WERKS = #{WERKS}
    and MATNR = #{MATNR}
    and MSRM_DATE = TO_DATE(#{MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
    and INSP_ITEM_GRP_CD = #{INSP_ITEM_GRP_CD}

mapper.insert:
MERGE INTO TB_QLT020 T
    USING DUAL ON (
            T.WERKS                 = #{WERKS}
            AND T.MATNR             = #{MATNR}
            and T.INSP_ITEM_GRP_CD  = #{INSP_ITEM_GRP_CD}
            AND T.MSRM_DATE         = TO_DATE(#{MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')

            AND T.LOT_NO           = #{LOT_NO}

        )
    WHEN MATCHED THEN
        UPDATE SET
            MSRM_ID     = #{MSRM_NM}
            , PRC_SEQNO = #{PRC_SEQNO}
            , FNL_JDGM  = #{FNL_JDGM}
            , RMK       = #{RMK}
            , UPDID     = #{REG_ID}
            , UPDDATE   = SYSDATE
    WHEN NOT MATCHED THEN
        INSERT (WERKS, MATNR, MSRM_DATE, PRC_SEQNO, INSP_ITEM_GRP_CD, MSRM_ID, LOT_NO, IND_BCD, LOT_NO_M, FNL_JDGM, REGID, REGDATE, RMK)
            VALUES (#{WERKS}, #{MATNR}, TO_DATE(#{MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
                   , #{PRC_SEQNO}, #{INSP_ITEM_GRP_CD}, #{MSRM_NM}, #{LOT_NO}, #{IND_BCD}, #{LOT_NO_M}, #{FNL_JDGM}, #{REG_ID}, SYSDATE, #{RMK})

