  , PRC_SEQNO   = #{PRC_SEQNO}
  , INSPR_ID    = #{REG_ID}
  , UPDDATE     = SYSDATE
  , UPDID       = #{REG_ID}
WHERE 1=1
    and WERKS       = #{WERKS}
    AND IND_BCD     = #{IND_BCD}
    AND MATNR       = #{MATNR}

