mapper.select:
SELECT PROD_KEY, WERKS, MACH_CD, MSRM_DATE, MSRM_TIME, -- PIVOT 결과 컬럼 매핑 (별칭을 명확히 NM, RT로 줄였습니다) -- 원료명 NVL 처리 (null이면 빈 문자열) NVL("1_NM", ' ') AS MAT_NM_1, NVL("1_QT", 0) AS USE_QTY_1, NVL("1_RT", 0) AS MIX_RATE_1, NVL("2_NM", ' ') AS MAT_NM_2, NVL("2_QT", 0) AS USE_QTY_2, NVL("2_RT", 0) AS MIX_RATE_2, NVL("3_NM", ' ') AS MAT_NM_3, NVL("3_QT", 0) AS USE_QTY_3, NVL("3_RT", 0) AS MIX_RATE_3, NVL("4_NM", ' ') AS MAT_NM_4, NVL("4_QT", 0) AS USE_QTY_4, NVL("4_RT", 0) AS MIX_RATE_4, NVL("5_NM", ' ') AS MAT_NM_5, NVL("5_QT", 0) AS USE_QTY_5, NVL("5_RT", 0) AS MIX_RATE_5, NVL("6_NM", ' ') AS MAT_NM_6, NVL("6_QT", 0) AS USE_QTY_6, NVL("6_RT", 0) AS MIX_RATE_6, NVL("7_NM", ' ') AS MAT_NM_7, NVL("7_QT", 0) AS USE_QTY_7, NVL("7_RT", 0) AS MIX_RATE_7, NVL("8_NM", ' ') AS MAT_NM_8, NVL("8_QT", 0) AS USE_QTY_8, NVL("8_RT", 0) AS MIX_RATE_8, -- 총사용량 합계 계산 (NVL("1_QT", 0) + NVL("2_QT", 0) + NVL("3_QT", 0) + NVL("4_QT", 0) + NVL("5_QT", 0) + NVL("6_QT", 0) + NVL("7_QT", 0) + NVL("8_QT", 0)) AS TOTAL_USE, -- 총비율 합계 계산 (NVL("1_RT", 0) + NVL("2_RT", 0) + NVL("3_RT", 0) + NVL("4_RT", 0) + NVL("5_RT", 0) + NVL("6_RT", 0) + NVL("7_RT", 0) + NVL("8_RT", 0)) || '%' AS TOTAL_RATE FROM ( -- 1. 데이터 소스 및 가상 순번 생성 SELECT PROD_KEY, WERKS, MACH_CD, MSRM_DATE, MSRM_TIME, MAT_NM, MIX_RATE, USE_QTY, MAT_SEQ FROM TB_QLT_PROD_SPEC A WHERE 1=1 AND A.WERKS = #{WERKS}
${RANGE_SQL}
AND EXISTS ( SELECT 1 FROM TB_QLT_PROD_SPEC B WHERE B.WERKS = A.WERKS AND B.PROD_KEY = A.PROD_KEY AND B.KPGBN = 'LBKP' AND B.MAT_NM LIKE '%' || #{MAT_NM_LB} || '%' )
AND EXISTS ( SELECT 1 FROM TB_QLT_PROD_SPEC C WHERE C.WERKS = A.WERKS AND C.PROD_KEY = A.PROD_KEY AND C.KPGBN = 'NBKP' AND C.MAT_NM LIKE '%' || #{MAT_NM_NB} || '%' )
) -- 2. PIVOT 실행 (별칭을 짧게 NM, RT로 설정) PIVOT ( MAX(MAT_NM) AS NM, MAX(MIX_RATE) AS RT, MAX(USE_QTY) AS QT FOR MAT_SEQ IN (1, 2, 3, 4, 5, 6, 7, 8) ) PVT -- 3. 정렬 ORDER BY MSRM_DATE DESC

select seq as SEQ, PROD_MM as PROD_MM, NO as NO, prod_date as PRD_DATE, prod_time as PRD_TIME, prod_line as MACHINE, inspector as INSP_USER, LOT_NO as LOT_NO_RA, item_code as MATNR, item_name as MATNR_NM, defect_grp AS DEFECT_GRP, defect_dtl AS DEFECT_DTL, defect_qty AS DEFECT_QTY, UNIT AS QLT_UNIT, 0 AS EA_CONV_QTY, defect_act AS DEFECT_ACT, remark AS RMK, reg_dt AS REG_DT, reg_user AS REG_USER from TB_QLT_DEFECT where 1 = 1
${RANGE_SQL}
AND prod_line LIKE '%' || #{MACHINE} || '%'

mapper.update:
MERGE INTO TB_QLT_DEFECT T USING (
SELECT #{item.SEQ} AS SEQ, #{item.PROD_MM} AS PROD_MM, #{item.NO} AS NO, #{item.PRD_DATE} AS PROD_DATE, #{item.PRD_TIME} AS PROD_TIME, #{item.MACHINE} AS PROD_LINE, #{item.LOT_NO_RA} AS LOT_NO, #{item.MATNR} AS ITEM_CODE, #{item.DEFECT_GRP} AS DEFECT_GRP, #{item.DEFECT_DTL} AS DEFECT_DTL, #{item.DEFECT_QTY} AS DEFECT_QTY, #{item.QLT_UNIT} AS UNIT, #{item.DEFECT_ACT} AS DEFECT_ACT, #{item.RMK} AS REMARK, #{item.REG_ID} AS REG_USER FROM DUAL
) S ON ( T.SEQ = S.SEQ ) WHEN MATCHED THEN UPDATE SET T.PROD_MM = S.PROD_MM, T.NO = S.NO, T.PROD_TIME = S.PROD_TIME, T.DEFECT_GRP = S.DEFECT_GRP, T.DEFECT_DTL = S.DEFECT_DTL, T.DEFECT_QTY = S.DEFECT_QTY, T.UNIT = S.UNIT, T.DEFECT_ACT = S.DEFECT_ACT, T.REMARK = S.REMARK, T.REG_DT = SYSDATE, T.REG_USER = S.REG_USER

