SELECT
    LPAD(NVL(MAX(TO_NUMBER(SUBSTR(PROD_KEY, -2))), 0) + 1, 2, '0') AS NEXT_SEQ
FROM TB_QLT_PROD_SPEC
WHERE WERKS     = #{WERKS}
  AND MACH_CD   = #{MACH_CD}
  AND MSRM_DATE = #{MSRM_DATE}

select SEQ AS SEQ , MACH_CD AS MACH_CD , INSPR_NM AS INSPR_NM , CREATEUSER AS REGID , CREATEDATE AS REGDATE , UPDATEUSER AS UPDID , UPDATEDATE AS UPDDATE , RMK1 AS QLT_USER_GRP , RMK2 AS USE_YN from TB_QLT_USER where 1=1
and RMK1 = #{QLT_USER_GRP}
and MACH_CD = #{MACH_CD}
order by RMK1, MACH_CD, INSPR_NM

select INSPR_NM AS VALUE_COL, INSPR_NM AS TEXT_COL from TB_QLT_USER where 1=1 and RMK2 = 'Y' --USE_YN
and RMK1 = #{QLT_USER_GRP}
order by RMK1, MACH_CD, INSPR_NM

mapper.insert:
INSERT INTO TB_QLT_USER ( SEQ, MACH_CD, INSPR_NM, CREATEUSER, CREATEDATE, RMK1, RMK2 ) SELECT (SELECT NVL(MAX(SEQ), 0) FROM TB_QLT_USER) + ROWNUM, A.MACH_CD, A.INSPR_NM, A.REGID, SYSDATE, A.QLT_USER_GRP, A.USE_YN FROM (
SELECT #{item.MACH_CD} AS MACH_CD, #{item.INSPR_NM} AS INSPR_NM, #{item.REGID} AS REGID, #{item.QLT_USER_GRP} AS QLT_USER_GRP, #{item.USE_YN} AS USE_YN FROM DUAL
) A

