SET INSPR_NM    = #{item.INSPR_NM}
, RMK2        = #{item.USE_YN}
, UPDATEDATE  = SYSDATE
, UPDATEUSER  = #{item.REGID}
WHERE SEQ       = #{item.SEQ};

